select #{item.assetUuid, jdbcType=CHAR} ASSET_UUID, #{item.assetCode ,jdbcType=VARCHAR } ASSET_CODE, #{item.assetsInvest ,jdbcType=VARCHAR } ASSETS_INVEST, #{item.eachProportion ,jdbcType=VARCHAR } EACH_PROPORTION, #{item.loansType ,jdbcType=VARCHAR } LOANS_TYPE, #{item.origCcy ,jdbcType=CHAR } ORIG_CCY, #{item.origContractAmount ,jdbcType=DECIMAL } ORIG_CONTRACT_AMOUNT, #{item.origContractAmountCny ,jdbcType=DECIMAL } ORIG_CONTRACT_AMOUNT_CNY, #{item.borrowerType ,jdbcType=CHAR } BORROWER_TYPE, #{item.borrowerId ,jdbcType=VARCHAR } BORROWER_ID, #{item.industryInfo ,jdbcType=CHAR } INDUSTRY_INFO, #{item.borrowerNationality ,jdbcType=VARCHAR } BORROWER_NATIONALITY, #{item.borrowerProvince ,jdbcType=VARCHAR } BORROWER_PROVINCE, #{item.borrowerCity ,jdbcType=VARCHAR } BORROWER_CITY, #{item.borrowerCounty ,jdbcType=VARCHAR } BORROWER_COUNTY, #{item.loanTransferorId ,jdbcType=VARCHAR } LOAN_TRANSFEROR_ID, #{item.loanTransferorName ,jdbcType=VARCHAR } LOAN_TRANSFEROR_NAME, #{item.loanContractOrgId ,jdbcType=VARCHAR } LOAN_CONTRACT_ORG_ID, #{item.loanContractOrgName ,jdbcType=VARCHAR } LOAN_CONTRACT_ORG_NAME, #{item.loanContractOrgProvince ,jdbcType=VARCHAR } LOAN_CONTRACT_ORG_PROVINCE, #{item.loanContractOrgCity ,jdbcType=VARCHAR } LOAN_CONTRACT_ORG_CITY, #{item.loanContractOrgCounty ,jdbcType=VARCHAR } LOAN_CONTRACT_ORG_COUNTY, #{item.enterpriseInvestorTypeFirst ,jdbcType=CHAR } ENTERPRISE_INVESTOR_TYPE_FIRST, #{item.enterpriseInvestorTypeSec ,jdbcType=CHAR } ENTERPRISE_INVESTOR_TYPE_SEC, #{item.enterpriseInvestorTypeThird ,jdbcType=CHAR } ENTERPRISE_INVESTOR_TYPE_THIRD, #{item.enterpriseScale ,jdbcType=CHAR } ENTERPRISE_SCALE, #{item.loanBasisId ,jdbcType=VARCHAR } LOAN_BASIS_ID, #{item.loanPrdType ,jdbcType=CHAR } LOAN_PRD_TYPE, #{item.loanActualInvest ,jdbcType=VARCHAR } LOAN_ACTUAL_INVEST, #{item.loanVdate ,jdbcType=DATE } LOAN_VDATE, #{item.loanMdate ,jdbcType=DATE } LOAN_MDATE, #{item.loanExtensionDueDate ,jdbcType=DATE } LOAN_EXTENSION_DUE_DATE, #{item.rateFixed ,jdbcType=VARCHAR } RATE_FIXED, #{item.rateLevel ,jdbcType=DECIMAL } RATE_LEVEL, #{item.loanGuaranteeMode ,jdbcType=CHAR } LOAN_GUARANTEE_MODE, #{item.loanQuality ,jdbcType=CHAR } LOAN_QUALITY, #{item.loanState ,jdbcType=CHAR } LOAN_STATE, #{item.loanTransferorRate ,jdbcType=DECIMAL } LOAN_TRANSFEROR_RATE, #{item.createUser ,jdbcType=VARCHAR } CREATE_USER, #{item.createTime ,jdbcType=TIMESTAMP } CREATE_TIME, #{item.updateUser ,jdbcType=VARCHAR } UPDATE_USER, #{item.updateTime ,jdbcType=TIMESTAMP } UPDATE_TIME, #{item.createDept ,jdbcType=VARCHAR } CREATE_DEPT, #{item.orgCode ,jdbcType=VARCHAR } ORG_CODE, #{item.deptCode ,jdbcType=VARCHAR } DEPT_CODE, #{item.status ,jdbcType=VARCHAR } STATUS, #{item.dataSource ,jdbcType=VARCHAR } DATA_SOURCE, #{item.assetType ,jdbcType=VARCHAR } ASSET_TYPE from dual
) TEMP where not exisits (select 1 from CHB_LOAN_DETAIL_INFO CII where CII.ASSET_CODE = TEMP.ASSET_CODE) ) de ;
