jdbcType=VARCHAR } RATE_FIXED, #{item.rateLevel ,jdbcType=DECIMAL } RATE_LEVEL, #{item.loanGuaranteeMode ,jdbcType=CHAR } LOAN_GUARANTEE_MODE, #{item.loanQuality ,jdbcType=CHAR } LOAN_QUALITY, #{item.loanState ,jdbcType=CHAR } LOAN_STATE, #{item.loanTransferorRate ,jdbcType=DECIMAL } LOAN_TRANSFEROR_RATE, #{item.createUser ,jdbcType=VARCHAR } CREATE_USER, #{item.createTime ,jdbcType=TIMESTAMP } CREATE_TIME, #{item.updateUser ,jdbcType=VARCHAR } UPDATE_USER, #{item.updateTime ,jdbcType=TIMESTAMP } UPDATE_TIME, #{item.createDept ,jdbcType=VARCHAR } CREATE_DEPT, #{item.orgCode ,jdbcType=VARCHAR } ORG_CODE, #{item.deptCode ,jdbcType=VARCHAR } DEPT_CODE, #{item.status ,jdbcType=VARCHAR } STATUS, #{item.dataSource ,jdbcType=VARCHAR } DATA_SOURCE, #{item.assetType ,jdbcType=VARCHAR } ASSET_TYPE from dual
) TEMP ) de ) AS B set A.* = B.* where exisits (select 1 from CHB_LOAN_DETAIL_INFO CII where CII.ASSET_CODE = TEMP.ASSET_CODE);

